/* CSS PART 2 OF 3 */

/* Company experience and approach */

.trust-section {
  padding-block: 76px;
  background: var(--white);
  border-bottom: 1px solid var(--line);
}

.trust-inner {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  align-items: center;
  gap: 70px;
}

.trust-lead {
  padding-right: 35px;
  border-right: 1px solid var(--line);
}

.trust-lead h2 {
  margin-bottom: 16px;
  font-size: clamp(2.4rem, 4vw, 3.7rem);
}

.trust-lead p {
  margin-bottom: 0;
  font-size: 0.95rem;
}

.trust-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 38px 42px;
}

.trust-fact {
  position: relative;
  padding-left: 23px;
  border-left: 3px solid var(--copper);
}

.trust-fact strong {
  display: block;
  margin-bottom: 7px;
  color: var(--navy-deep);
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
  line-height: 1.1;
}

.trust-fact span {
  color: var(--ink-soft);
  font-size: 0.88rem;
  line-height: 1.6;
}

/* Services */

.services-section {
  padding-block: var(--section-space);
  background: var(--paper);
}

.services-intro {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 50px;
  margin-bottom: 55px;
}

.services-intro .section-heading {
  margin-bottom: 0;
}

.services-intro .section-intro {
  max-width: 400px;
  margin-bottom: 8px;
}

.service-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.service-item {
  position: relative;
  min-height: 240px;
  padding: 35px 32px 38px 0;
}

.service-item + .service-item {
  padding-left: 32px;
  border-left: 1px solid var(--line);
}

.service-number {
  display: block;
  margin-bottom: 28px;
  color: var(--copper-dark);
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.service-item h3 {
  margin-bottom: 13px;
}

.service-item p {
  max-width: 330px;
  margin-bottom: 0;
  font-size: 0.92rem;
  line-height: 1.8;
}

/* Roofing guidance */

.roof-section {
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  align-items: stretch;
  background: var(--navy);
}

.roof-image {
  min-height: 620px;
  overflow: hidden;
}

.roof-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.roof-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(55px, 8vw, 110px);
}

.roof-content .eyebrow {
  color: #e9b18d;
}

.roof-content h2 {
  max-width: 580px;
  margin-bottom: 25px;
  color: var(--white);
}

.roof-content > p {
  max-width: 570px;
  color: rgba(255, 255, 255, 0.82);
}

.roof-steps {
  display: grid;
  gap: 0;
  margin-top: 25px;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
}

.roof-step {
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 16px;
  padding-block: 19px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
}

.roof-step-number {
  color: #e9b18d;
  font-family: var(--font-heading);
  font-size: 1.3rem;
  font-weight: 800;
}

.roof-step h3 {
  margin-bottom: 5px;
  color: var(--white);
  font-family: var(--font-body);
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0;
}

.roof-step p {
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.76);
  font-size: 0.85rem;
  line-height: 1.65;
}

/* Recent projects */

.projects-section {
  padding-block: var(--section-space);
  background: var(--white);
}

.projects-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: 48px;
}

.projects-header .section-heading {
  margin-bottom: 0;
}

.projects-header .section-intro {
  max-width: 380px;
  margin-bottom: 5px;
}

.project-gallery {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  grid-template-rows: repeat(2, minmax(260px, 1fr));
  gap: 20px;
}

.project-card {
  position: relative;
  min-width: 0;
  min-height: 280px;
  overflow: hidden;
  background: var(--stone);
}

.project-card:first-child {
  grid-row: span 2;
  min-height: 580px;
}

.project-card img {
  width: 100%;
  height: 100%;
  min-height: inherit;
  object-fit: cover;
  transition: transform 500ms ease;
}

.project-card:hover img {
  transform: scale(1.035);
}

.project-caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 38px 25px 22px;
  background: linear-gradient(
    0deg,
    rgba(20, 37, 47, 0.88),
    rgba(20, 37, 47, 0)
  );
  color: var(--white);
}

.project-caption span {
  display: block;
  margin-bottom: 5px;
  color: #f0b894;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.project-caption h3 {
  margin-bottom: 0;
  color: var(--white);
  font-size: 1.65rem;
}

/* Project image treatment and content rhythm */

.project-card:focus-within {
  outline: 3px solid var(--copper);
  outline-offset: 4px;
}

.project-card img,
.roof-image img,
.hero-media img {
  backface-visibility: hidden;
}
