/* CSS PART 3 OF 3 */

/* Contact and conversion */

.contact-section {
  padding-block: var(--section-space);
  background: var(--paper);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: clamp(45px, 8vw, 105px);
  align-items: start;
}

.contact-copy {
  padding-top: 12px;
}

.contact-copy h2 {
  margin-bottom: 22px;
}

.contact-copy > p {
  max-width: 430px;
}

.contact-details {
  display: grid;
  gap: 14px;
  margin-top: 38px;
}

.contact-link {
  display: flex;
  align-items: center;
  gap: 15px;
  color: var(--navy);
  font-weight: 800;
  transition: color var(--transition);
}

.contact-link:hover {
  color: var(--copper-dark);
}

.contact-link-icon {
  display: grid;
  width: 43px;
  height: 43px;
  flex: 0 0 43px;
  place-items: center;
  border: 1px solid var(--line);
  color: var(--copper-dark);
  font-size: 1.1rem;
}

.contact-form-wrap {
  padding: clamp(28px, 4vw, 48px);
  background: var(--white);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
}

.contact-form-wrap h3 {
  margin-bottom: 10px;
  font-size: 2rem;
}

.form-intro {
  margin-bottom: 28px;
  font-size: 0.9rem;
}

.contact-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field-full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--navy-deep);
  font-size: 0.8rem;
  font-weight: 800;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-height: 51px;
  padding: 12px 14px;
  border: 1px solid #cfcec7;
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
  outline-offset: 2px;
  transition:
    border-color var(--transition),
    background var(--transition);
}

.form-field textarea {
  min-height: 145px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #777f80;
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  border-color: var(--copper-dark);
  background: var(--white);
}

.contact-form .button {
  grid-column: 1 / -1;
  width: 100%;
  margin-top: 4px;
}

.form-disclaimer {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--muted);
  font-size: 0.75rem;
  line-height: 1.6;
}

/* Footer */

.site-footer {
  padding-block: 55px 25px;
  background: var(--navy-deep);
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
  padding-bottom: 35px;
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-tagline {
  color: rgba(255, 255, 255, 0.65);
}

.footer-contact {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 15px 30px;
}

.footer-contact a {
  color: rgba(255, 255, 255, 0.88);
  font-size: 0.88rem;
  font-weight: 700;
  transition: color var(--transition);
}

.footer-contact a:hover {
  color: #f0b894;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.18);
}

.footer-bottom p {
  margin: 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.76rem;
}

/* Responsive layout */

@media (max-width: 1000px) {
  :root {
    --gutter: 30px;
    --section-space: 85px;
  }

  .header-inner {
    gap: 20px;
  }

  .main-nav {
    gap: 15px;
  }

  .main-nav a:not(.button) {
    font-size: 0.76rem;
  }

  .trust-inner {
    grid-template-columns: 1fr 1.3fr;
    gap: 40px;
  }

  .trust-facts {
    gap: 28px;
  }

  .roof-content {
    padding: 55px 40px;
  }

  .contact-layout {
    gap: 45px;
  }
}

@media (max-width: 760px) {
  :root {
    --gutter: 22px;
    --section-space: 72px;
  }

  html {
    scroll-padding-top: 20px;
  }

  .header-inner {
    min-height: auto;
    flex-wrap: wrap;
    gap: 14px;
    padding-block: 15px;
  }

  .brand img {
    width: 49px;
    max-height: 49px;
  }

  .brand-name {
    font-size: 1.12rem;
  }

  .brand-tagline {
    font-size: 0.58rem;
  }

  .main-nav {
    width: 100%;
    justify-content: flex-start;
    gap: 18px;
    overflow-x: auto;
    padding: 5px 0;
    scrollbar-width: thin;
  }

  .main-nav a:not(.button) {
    flex: 0 0 auto;
    font-size: 0.8rem;
  }

  .main-nav .button {
    min-height: 42px;
    flex: 0 0 auto;
    padding: 10px 15px;
    font-size: 0.76rem;
  }

  .hero {
    min-height: 660px;
    min-height: min(740px, 88svh);
  }

  .hero::before {
    background: linear-gradient(
      90deg,
      rgba(20, 37, 47, 0.94),
      rgba(20, 37, 47, 0.68)
    );
  }

  .hero-content {
    padding-block: 85px;
  }

  .hero h1 {
    font-size: clamp(3.1rem, 13vw, 5rem);
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .trust-inner {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .trust-lead {
    padding-right: 0;
    padding-bottom: 25px;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .trust-facts {
    gap: 25px;
  }

  .services-intro,
  .projects-header {
    align-items: flex-start;
    flex-direction: column;
    gap: 15px;
  }

  .services-intro .section-intro,
  .projects-header .section-intro {
    max-width: 600px;
  }

  .service-list {
    grid-template-columns: 1fr;
  }

  .service-item {
    min-height: auto;
    padding: 27px 0;
  }

  .service-item + .service-item {
    padding-left: 0;
    border-top: 1px solid var(--line);
    border-left: 0;
  }

  .service-number {
    margin-bottom: 14px;
  }

  .roof-section {
    grid-template-columns: 1fr;
  }

  .roof-image {
    min-height: 0;
    height: 340px;
  }

  .roof-content {
    padding: 65px var(--gutter);
  }

  .project-gallery {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto;
    gap: 12px;
  }

  .project-card,
  .project-card:first-child {
    grid-row: auto;
    min-height: 260px;
  }

  .project-card:first-child {
    grid-column: 1 / -1;
    min-height: 380px;
  }

  .project-caption {
    padding: 35px 16px 17px;
  }

  .project-caption h3 {
    font-size: 1.35rem;
  }

  .contact-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .contact-details {
    margin-top: 25px;
  }

  .footer-main {
    align-items: flex-start;
    flex-direction: column;
  }

  .footer-bottom {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 480px) {
  :root {
    --gutter: 18px;
    --section-space: 60px;
  }

  body {
    font-size: 15px;
  }

  .eyebrow {
    font-size: 0.66rem;
  }

  .hero {
    min-height: 650px;
  }

  .hero h1 {
    font-size: clamp(2.9rem, 14vw, 4rem);
  }

  .trust-facts {
    grid-template-columns: 1fr 1fr;
    gap: 22px 15px;
  }

  .trust-fact {
    padding-left: 13px;
  }

  .trust-fact strong {
    font-size: 1.65rem;
  }

  .roof-image {
    height: 270px;
  }

  .roof-content {
    padding-block: 55px;
  }

  .project-gallery {
    grid-template-columns: 1fr;
  }

  .project-card,
  .project-card:first-child {
    grid-column: auto;
    min-height: 290px;
  }

  .contact-form-wrap {
    padding: 24px 18px;
  }

  .contact-form {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .form-field-full,
  .contact-form .button,
  .form-disclaimer {
    grid-column: auto;
  }

  .footer-contact {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }
}

/* Accessible interaction and motion preferences */

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--copper);
  outline-offset: 4px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
